"""U-LOOP-003: synthetic held-out set (no download). Lengths 1..40, 50 examples per length and task, generated with a
secret seed by the same generator the agent sees (harness/algo_tasks.py). There is no public data file."""
from __future__ import annotations

import importlib.util
import os
import sys
from pathlib import Path

from prepare.common import Frozen

HARNESS = Path(__file__).resolve().parents[2] / "cases" / "U-LOOP-003" / "harness"
SOURCES = [{"name": "synthetic algorithmic tasks", "generator": "cases/U-LOOP-003/harness/algo_tasks.py",
            "license": "generated by ABench"}]


def _stages():
    sys.path.insert(0, str(HARNESS))
    spec = importlib.util.spec_from_file_location("u_loop_stages", HARNESS / "stages.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def build(raw: Path) -> Frozen:
    seed = int(os.environ.get("ABENCH_U_LOOP_SEED", "0"))
    if not seed:
        raise SystemExit("set ABENCH_U_LOOP_SEED to a secret integer (the generator seed of the held-out set)")
    st = _stages()
    d = st.build_split(seed, range(1, 41), st.PER_LENGTH)
    return Frozen(public={}, hidden=d, sources_sha256={"generator": "algo_tasks.py", "seed": "secret (operator)"})


def synthetic(n: int) -> Frozen:
    st = _stages()
    return Frozen(public={}, hidden=st.build_split(7, range(1, 41), max(2, n // 40)), sources_sha256={"synthetic": f"n{n}"})
